document.addEventListener('DOMContentLoaded',()=>{const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const csrfToken=document.querySelector('meta[name="csrf-token"]')?.content;const navToggle=document.querySelector('.nav-toggle');const navLinks=document.querySelector('#primary-links');const printResume=document.querySelector('[data-print-resume]');const topProgress=document.querySelector('.top-progress');const navbar=document.querySelector('.navbar');document.body.classList.add('motion-ready');document.querySelectorAll('.nav-links a.active').forEach((link)=>link.setAttribute('aria-current','page'));if(printResume){printResume.addEventListener('click',()=>window.print());}
if(csrfToken){document.querySelectorAll('form[method="post"], form[method="POST"]').forEach((form)=>{if(form.querySelector('input[name="csrf_token"]')){return;}
const input=document.createElement('input');input.type='hidden';input.name='csrf_token';input.value=csrfToken;form.appendChild(input);});}
document.querySelectorAll('form[data-confirm]').forEach((form)=>{form.addEventListener('submit',(event)=>{if(!window.confirm(form.dataset.confirm||'Are you sure?')){event.preventDefault();}});});if(navToggle&&navLinks){navToggle.addEventListener('click',()=>{const willOpen=navToggle.getAttribute('aria-expanded')!=='true';navToggle.setAttribute('aria-expanded',willOpen?'true':'false');navLinks.classList.toggle('is-open',willOpen);});navLinks.addEventListener('click',(event)=>{if(event.target.closest('a')){navToggle.setAttribute('aria-expanded','false');navLinks.classList.remove('is-open');}});}
document.querySelectorAll('.profile-menu').forEach((menu)=>{const trigger=menu.querySelector('.profile-trigger');if(!trigger){return;}
trigger.addEventListener('click',(event)=>{event.stopPropagation();const willOpen=!menu.classList.contains('is-open');menu.classList.toggle('is-open',willOpen);trigger.setAttribute('aria-expanded',willOpen?'true':'false');});});document.addEventListener('click',()=>{document.querySelectorAll('.profile-menu.is-open').forEach((menu)=>{menu.classList.remove('is-open');menu.querySelector('.profile-trigger')?.setAttribute('aria-expanded','false');});});document.addEventListener('keydown',(event)=>{if(event.key!=='Escape'){return;}
if(navLinks?.classList.contains('is-open')){navLinks.classList.remove('is-open');navToggle?.setAttribute('aria-expanded','false');navToggle?.focus();}
document.querySelectorAll('.profile-menu.is-open').forEach((menu)=>{menu.classList.remove('is-open');const trigger=menu.querySelector('.profile-trigger');trigger?.setAttribute('aria-expanded','false');trigger?.focus();});});const revealItems=[...document.querySelectorAll('.reveal')];revealItems.forEach((item)=>{const siblings=[...(item.parentElement?.children||[])].filter((child)=>child.classList.contains('reveal'));const siblingIndex=Math.max(0,siblings.indexOf(item));item.style.setProperty('--reveal-delay',`${Math.min(siblingIndex * 70, 280)}ms`);});if(!reduceMotion&&'IntersectionObserver'in window){const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{rootMargin:'0px',threshold:0});revealItems.forEach((item)=>observer.observe(item));}else{revealItems.forEach((item)=>item.classList.add('is-visible'));}
if(!reduceMotion&&window.matchMedia('(hover: hover) and (pointer: fine)').matches){document.querySelectorAll('.project-card, .article-card, .media-card, .social-card, .deck-card, .snap-card').forEach((card)=>{card.addEventListener('pointermove',(event)=>{const bounds=card.getBoundingClientRect();const x=((event.clientX-bounds.left)/bounds.width)*100;const y=((event.clientY-bounds.top)/bounds.height)*100;card.style.setProperty('--mx',`${x.toFixed(1)}%`);card.style.setProperty('--my',`${y.toFixed(1)}%`);},{passive:true});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--mx');card.style.removeProperty('--my');});});}
let scrollQueued=false;const updateScrollUi=()=>{scrollQueued=false;const scrollable=document.documentElement.scrollHeight-window.innerHeight;const progress=scrollable>0?window.scrollY/scrollable:0;if(topProgress){topProgress.style.transform=`scaleX(${Math.min(1, Math.max(0, progress))})`;}
navbar?.classList.toggle('nav-scrolled',window.scrollY>12);backToTop.classList.toggle('is-visible',window.scrollY>700);};const requestScrollUpdate=()=>{if(!scrollQueued){scrollQueued=true;window.requestAnimationFrame(updateScrollUi);}};const backToTop=document.createElement('button');backToTop.type='button';backToTop.className='back-to-top';backToTop.setAttribute('aria-label','Back to top');backToTop.textContent='Top';backToTop.addEventListener('click',()=>{window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});});document.body.appendChild(backToTop);window.addEventListener('scroll',requestScrollUpdate,{passive:true});updateScrollUi();document.querySelectorAll('.share-button').forEach((button)=>{button.addEventListener('click',async()=>{const url=button.dataset.shareUrl||window.location.href;const title=button.dataset.shareTitle||document.title;try{if(navigator.share){await navigator.share({title,url});return;}
await navigator.clipboard.writeText(url);const original=button.textContent;button.textContent='Link copied';window.setTimeout(()=>{button.textContent=original;},1500);}catch(error){}});});document.querySelectorAll('.email-action').forEach((button)=>{button.addEventListener('click',(event)=>{event.preventDefault();const mailto=button.dataset.mailto||button.getAttribute('href');const email=button.dataset.email||'';const status=document.querySelector('.mail-status');if(mailto){window.location.href=mailto;}
if(status){status.textContent=email?`If no email draft opened, write to ${email}.`:'If no email draft opened, use your preferred email application.';}});});const photoLinks=document.querySelectorAll('.photo-card .media-link');if(photoLinks.length){const lightbox=document.createElement('dialog');lightbox.className='media-lightbox';lightbox.setAttribute('role','dialog');lightbox.setAttribute('aria-modal','true');lightbox.setAttribute('aria-label','Photo preview');lightbox.innerHTML='<button type="button" class="media-lightbox-close">Close</button><img alt="">';document.body.appendChild(lightbox);const preview=lightbox.querySelector('img');const close=lightbox.querySelector('button');const closeLightbox=()=>{lightbox.classList.remove('is-open');lightbox.close();document.body.classList.remove('lightbox-open');preview.removeAttribute('src');};photoLinks.forEach((link)=>{link.addEventListener('click',(event)=>{if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey){return;}
const image=link.querySelector('img');if(!image){return;}
event.preventDefault();preview.src=link.dataset.fullImage||image.src;preview.alt=image.alt;lightbox.classList.add('is-open');lightbox.showModal();document.body.classList.add('lightbox-open');close.focus();});});close.addEventListener('click',closeLightbox);lightbox.addEventListener('cancel',(event)=>{event.preventDefault();closeLightbox();});lightbox.addEventListener('click',(event)=>{if(event.target===lightbox){closeLightbox();}});}});